Here is the commit message:
xfs: get rid of the xchk_xfile_*_descr calls

The xchk_xfile_*_descr macros call kasprintf, which can fail to allocate
memory if the formatted string is larger than 16 bytes (or whatever the
nofail guarantees are nowadays).  Some of them could easily exceed that,
and Jiaming Zhang found a few places where that can happen with syzbot.

The descriptions are debugging aids and aren't required to be unique, so
let's just pass in static strings and eliminate this path to failure.
Note this patch touches a number of commits, most of which were merged
between 6.6 and 6.14.

Cc: r772577952@gmail.com
Cc: <stable@vger.kernel.org> # v6.12
Fixes: ab97f4b1c03075 ("xfs: repair AGI unlinked inode bucket lists")
Signed-off-by: "Darrick J. Wong" <djwong@kernel.org>
Reviewed-by: Christoph Hellwig <hch@lst.de>
Tested-by: Jiaming Zhang <r772577952@gmail.com>

Here is the root cause:
The `xchk_xfile_*_descr` macros use `kasprintf` to generate dynamic description strings (e.g., including AG, inode, or rtgroup numbers). Under memory pressure, `kasprintf` can fail when the formatted string exceeds a small threshold (≈16 bytes), causing `-ENOMEM` errors during `xfarray_create()` or `xfblob_create()` calls in various repair/scrub paths.

Here is the patch:
 /* Repair the AGI. */
 int
 xrep_agi(
 	struct xfs_scrub	*sc)
 {
 	struct xrep_agi		*ragi;
 	struct xfs_mount	*mp = sc->mp;
-	char			*descr;
 	unsigned int		i;
 	int			error;

 	/* We require the rmapbt to rebuild anything. */
 	if (!xfs_has_rmapbt(mp))
 		return -EOPNOTSUPP;

 	sc->buf = kzalloc(sizeof(struct xrep_agi), XCHK_GFP_FLAGS);
 	if (!sc->buf)
 		return -ENOMEM;
 	ragi = sc->buf;
 	ragi->sc = sc;

 	ragi->fab[XREP_AGI_INOBT] = (struct xrep_find_ag_btree){
 		.rmap_owner	= XFS_RMAP_OWN_INOBT,
 		.buf_ops	= &xfs_inobt_buf_ops,
 		.maxlevels	= M_IGEO(sc->mp)->inobt_maxlevels,
 	};
 	ragi->fab[XREP_AGI_FINOBT] = (struct xrep_find_ag_btree){
 		.rmap_owner	= XFS_RMAP_OWN_INOBT,
 		.buf_ops	= &xfs_finobt_buf_ops,
 		.maxlevels	= M_IGEO(sc->mp)->inobt_maxlevels,
 	};
 	ragi->fab[XREP_AGI_END] = (struct xrep_find_ag_btree){
 		.buf_ops	= NULL,
 	};

 	for (i = 0; i < XFS_AGI_UNLINKED_BUCKETS; i++)
 		ragi->iunlink_heads[i] = NULLAGINO;

 	xagino_bitmap_init(&ragi->iunlink_bmp);
 	sc->buf_cleanup = xrep_agi_buf_cleanup;

-	descr = xchk_xfile_ag_descr(sc, "iunlinked next pointers");
-	error = xfarray_create(descr, 0, sizeof(xfs_agino_t),
-			&ragi->iunlink_next);
-	kfree(descr);
+	error = xfarray_create("iunlinked next pointers", 0,
+			sizeof(xfs_agino_t), &ragi->iunlink_next);
 	if (error)
 		return error;

-	descr = xchk_xfile_ag_descr(sc, "iunlinked prev pointers");
-	error = xfarray_create(descr, 0, sizeof(xfs_agino_t),
-			&ragi->iunlink_prev);
-	kfree(descr);
+	error = xfarray_create("iunlinked prev pointers", 0,
+			sizeof(xfs_agino_t), &ragi->iunlink_prev);
 	if (error)
 		return error;

 	/*
 	 * Make sure we have the AGI buffer, as scrub might have decided it
 	 * was corrupt after xfs_ialloc_read_agi failed with -EFSCORRUPTED.
 	 */
 	error = xfs_trans_read_buf(mp, sc->tp, mp->m_ddev_targp,
 			XFS_AG_DADDR(mp, pag_agno(sc->sa.pag),
 						XFS_AGI_DADDR(mp)),
 			XFS_FSS_TO_BB(mp, 1), 0, &ragi->agi_bp, NULL);
 	if (error)
 		return error;
 	ragi->agi_bp->b_ops = &xfs_agi_buf_ops;

 	/* Find the AGI btree roots. */
 	error = xrep_agi_find_btrees(ragi);
 	if (error)
 		return error;

 	error = xrep_iunlink_rebuild_buckets(ragi);
 	if (error)
 		return error;

 	/* Last chance to abort before we start committing fixes. */
 	if (xchk_should_terminate(sc, &error))
 		return error;

 	/* Start rewriting the header and implant the btrees we found. */
 	xrep_agi_init_header(ragi);
 	xrep_agi_set_roots(ragi);
 	error = xrep_agi_calc_from_btrees(ragi);
 	if (error)
 		goto out_revert;
 	error = xrep_iunlink_commit(ragi);
 	if (error)
 		goto out_revert;

 	/* Reinitialize in-core state. */
 	return xrep_agi_commit_new(ragi);

 out_revert:
 	/* Mark the incore AGI state stale and revert the AGI. */
 	clear_bit(XFS_AGSTATE_AGI_INIT, &sc->sa.pag->pag_opstate);
 	memcpy(ragi->agi_bp->b_addr, &ragi->old_agi, sizeof(struct xfs_agi));
 	return error;
 }


